window.__APP_PARTS=window.__APP_PARTS||[];window.__APP_PARTS[0]="{\"version\":\"26.0\",\"updated\":\"2026-10-18\",\"profile\":{\"name\":\"서민규\",\"alias\":\"새야\",\"english\":\"SEO MIN GYU\",\"role\":\"GAME SCENARIO WRITER · WEB NOVEL AUTHOR\",\"headline\":\"이야기를 쓰고,\\n플레이 경험으로 연결합니다.\",\"deck\":\"상업 출시 게임 3종의 메인 시나리오 작업을 수행한 시나리오 라이터이자, 웹소설 연재와 완결 경험을 가진 작가입니다.\",\"about\":\"캐릭터 설정과 플롯 구성, 분기·대사 집필, 스크립트와 연출까지 게임 시나리오 제작 전반을 경험했습니다. 장편 웹소설에서 축적한 서사 구성 경험을 게임의 선택과 상호작용에 맞게 발전시키고, Unity 실습으로 기획의 구현과 플레이 검증을 이해해 왔습니다.\",\"academic\":\"여주대학교 게임 기획 비즈니스과 · 중퇴\",\"training\":\"디벨로켓 · 게임 기획/프로그래밍 교육 수료 (2026.03.27–10.17)\",\"email\":\"\",\"socialUrl\":\"https://x.com/saeya020\",\"blogUrl\":\"https://blog.naver.com/saeya020\"},\"projects\":[{\"id\":\"nyangnyang_survival\",\"title\":\"냥냥 서바이벌\",\"kind\":\"personal\",\"year\":\"2026\",\"period\":\"2026.08.26 — 2026.09.20\",\"studio\":\"개인 프로젝트 · 디벨로켓 교육 실습\",\"role\":\"게임 기획 · Unity 구현 · 테스트\",\"genre\":\"탑다운 덱빌딩 뱀서라이크\",\"short\":\"Unity·AI 개발 도구를 활용한 게임 제작 실습. 기획서 변경과 실제 기능 구현을 대조하고 플레이로그 수집 기능을 추가한 프로젝트.\",\"description\":\"탐험가 고양이가 초원과 숲을 배경으로 다섯 개 스테이지를 진행하며 무기와 보상 카드를 조합하는 탑다운 덱빌딩 뱀서라이크 게임입니다. Unity 6.3 LTS(URP)로 개발했으며, 2026년 8월 26일 프로젝트 생성 후 9월 11일부터 본격 개발해 9월 20일 Ver.0.1.5 빌드를 제작했습니다. 기획 변경 사항을 GDD에 반영하고 보스 패턴, 보상 시스템, UI와 사운드 등을 구현·검증했습니다.\",\"public\":true,\"featured\":false,\"featuredRank\":0,\"links\":[{\"label\":\"외부 공유용 데모·플레이 영상 폴더\",\"url\":\"https://drive.google.com/drive/folders/1R46iT1cCA3jsqMXUCUcP4tlH9JwVuWA0\"},{\"label\":\"외부 공개 빌드 · 플레이 테스트\",\"url\":\"https://drive.google.com/drive/folders/12gWZaXRBrryVF-iDnsFD7wORvhg3khOG?usp=drive_link\"}],\"platforms\":[],\"review\":{\"summary\":\"\",\"stats\":[],\"links\":[]},\"workFiles\":[],\"workLinks\":[{\"label\":\"게임 데모·플레이 영상 폴더 (공유 권한 필요)\",\"url\":\"https://drive.google.com/drive/folders/1R46iT1cCA3jsqMXUCUcP4tlH9JwVuWA0\"}],\"workNote\":\"\",\"contributions\":[\"콘셉트·레벨·보상 및 전투 규칙 기획 문서 작성\",\"Unity 기능 구현 및 Claude·Codex 활용 개발\",\"Play 모드 기능 검증, 플레이로그 분석, 설문 조사 정리\",\"기획 목표 대비 플레이 시간과 난이도 차이 분석 및 개선 항목 도출\"],\"outcomes\":[\"2026.09.20 Ver.0.1.5 테스트 빌드 제작\",\"GDD v2.0 갱신 · 보스 및 보상 시스템 구현·검증\",\"플레이로그 수집 시스템 및 사용자 동의 화면 구현 (추가 데이터 기반 밸런스 조정은 향후 과제)\"],\"theme\":\"jade\",\"english\":\"NYANG NYANG SURVIVAL\",\"coverImageData\":\"data:image/jpeg;base64,\",\"imageAttribution\":\"게임 개발일지 1쪽 · 타이틀 화면 (2026.09.15)\",\"coverImage\":\"\",\"coverType\":\"title_art\",\"caseStudy\":{\"version\":1,\"eyebrow\":\"UNITY PROJECT · GAME DESIGN · QA\",\"headline\":\"문서로 설계한 규칙을 구현하고, 플레이 결과에서 개선할 지점을 확인했습니다.\",\"summary\":\"5개 스테이지·3개 웨이브의 전투 구조, 보상 선택 시스템과 플레이로그 수집 기능을 구현했습니다. 레벨 구성표와 보상 데이터를 정리한 뒤 Unity Play 모드와 플레이 기록을 통해 일부 기능을 검증했습니다.\",\"meta\":[[\"프로젝트\",\"개인 개발 실습\"],[\"개발\",\"2026.08.26 — 09.20\"],[\"엔진\",\"Unity 6.3 LTS · URP\"],[\"도구\",\"Claude Code · Unity MCP · Git\"]],\"metrics\":[{\"value\":\"5\",\"label\":\"전투 스테이지\",\"detail\":\"스테이지당 3개 웨이브\"},{\"value\":\"26\",\"label\":\"분석 대상 플레이 로그\",\"detail\":\"39건 중 테스트 표시 13건 제외\"},{\"value\":\"6.5분\",\"label\":\"평균 클리어 시간\",\"detail\":\"목표 15~25분 대비 짧음\"},{\"value\":\"14\",\"label\":\"기능 검증 항목\",\"detail\":\"테스트 보고서 Play 모드 측정\"}],\"timeline\":[{\"date\":\"08.26\",\"title\":\"프로젝트 생성\",\"detail\":\"연습·평가용 초안을 구축하며 전투 기본 골격 마련\"},{\"date\":\"09.11\",\"title\":\"본격 구현 시작\",\"detail\":\"이동·공격·보상 3택 1 등 핵심 시스템 정비\"},{\"date\":\"09.15\",\"title\":\"게임 기획 문서 개정 전환\",\"detail\":\"고양이 몬스터·초원/숲 테마로 통일, 보스·레벨 데이터 갱신\"},{\"date\":\"09.18\",\"title\":\"테스트 데이터 수집\",\"detail\":\"플레이로그 기록·Google Forms 전송 및 동의 UI 추가\"},{\"date\":\"09.20\",\"title\":\"Ver.0.1.5 빌드·보고서\",\"detail\":\"보상/보스 수정 및 Play 모드 기능 검증, 테스트 결과 정리\"}],\"cases\":[{\"num\":\"01\",\"label\":\"레벨 디자인 · 기획 변경\",\"title\":\"기획서 개정에 맞춰 테마를 정리하고, 전투 차별화 방식을 바꿨습니다.\",\"issue\":\"초기 기획서에는 스테이지별로 늪·설원·화염·심해 등 다른 몬스터와 배경을 설정했습니다. 9월 15일 레벨 디자인 수정본에서는 모든 적을 고양이로 통일하고 초원·숲을 배경으로 고정하도록 방향이 변경됐습니다.\",\"action\":\"적을 모두 고양이로 통일하고 공간을 초원·숲으로 한정했습니다. 대신 적의 역할, 공격 패턴, 색상, 장식과 보스 행동으로 각 스테이지의 체감 차이를 설계하고, 9월 15일 게임 기획 문서 v2.0과 데이터에 반영했습니다.\",\"result\":\"다섯 스테이지의 테마를 통일하면서도 전투 역할과 난이도 구성으로 구분하는 기준을 마련했습니다.\",\"images\":[{\"key\":\"prototype\",\"caption\":\"초기 임시 캡슐 모델 · 개발일지 7쪽\"},{\"key\":\"characters\",\"caption\":\"고양이 모델을 적용한 전투 화면 · 개발일지 8쪽\"}]},{\"num\":\"02\",\"label\":\"보스 패턴 · 피드백 정합성\",\"title\":\"공격 의도와 실제 판정이 일치하도록 규칙을 조정했습니다.\",\"issue\":\"직선 공격은 기획 데이터의 사거리와 코드 판정 길이가 달랐고, 원형 공격은 지면의 경고 크기와 실제 피해 반경이 일치하지 않았습니다. 플레이어가 위험을 예상하기 어려운 상태였습니다.\",\"action\":\"직선 공격 판정 길이를 데이터 사거리와 맞추고, 원형 공격의 반경을 effectRadius로 통일했습니다. 보스 공격 규칙과 경고 표시를 플레이 화면에서 검증하고 문제를 수정했습니다.\",\"result\":\"게임의 안내와 실제 공격 판정이 어긋나는 문제를 해결한 사례입니다. 다만 전체 보스 밸런스는 후속 검토 항목으로 남겼습니다.\",\"images\":[{\"key\":\"boss\",\"caption\":\"고양이 보스 전투 확인 화면 · 개발일지 9쪽\"}]},{\"num\":\"03\",\"label\":\"보상 설계 · 정보 전달\",\"title\":\"플레이어의 성장 선택이 화면과 규칙에서 명확하게 전달되도록 개선했습니다.\",\"issue\":\"보상 카드 수치 및 설명과 실제 구현 값이 달라지는 문제가 있었고, 획득 보상과 속성 중첩 정보를 플레이어가 확인할 수 있는 UI도 필요했습니다.\",\"action\":\"9월 19일 동일 속성 재획득 시 최대 5회 중첩되도록 규칙과 시각 효과를 적용하고, 획득 보상·중첩·상세 설명을 보여주는 상태 패널을 추가했습니다. 9월 20일 기획 문서와 보상 카드 데이터와 기획 문서를 대조해 설명·수치를 확인했습니다.\",\"result\":\"보상 선택의 결과와 현재 성장 상태를 확인할 수 있게 했고, 일부 변경 사항을 Play 모드 기능 검증으로 확인했습니다.\",\"images\":[{\"key\":\"reward\",\"caption\":\"보상 카드 3택 1 화면 · 개발일지 16쪽\"},{\"key\":\"status\",\"caption\":\"획득 보상 표시 상태 패널 · 개발일지 16쪽\"}]}],\"qa\":{\"title\":\"실제 플레이에서 발견한 다음 과제\",\"context\":\"9월 18~19일 플레이로그와 설문, 9월 20일 기능 검증 결과를 보고서로 정리했습니다.\",\"metrics\":[{\"value\":\"39건\",\"label\":\"수집 로그\",\"note\":\"테스트 표시 포함\"},{\"value\":\"26회\",\"label\":\"분석한 플레이 기록\",\"note\":\"중복 플레이 가능, 참여자 수 아님\"},{\"value\":\"22회\",\"label\":\"분석 로그의 클리어\",\"note\":\"22/26 · 약 84.6%\"},{\"value\":\"6.5분\",\"label\":\"클리어 평균\",\"note\":\"목표 15~25분\"}],\"finding\":\"평균 클리어 시간은 GDD 목표의 절반보다 짧고, 보스전 이전의 웨이브도 설계 목표에 비해 빠르게 종료됐습니다. 완성된 밸런스라고 평가하기보다 난이도와 게임 길이가 부족하다는 개선 과제를 분리했습니다.\",\"implemented\":\"속성 중첩과 획득 보상 정보 표시는 9월 19일 업데이트에 반영했습니다. 보상·전투 기능 일부는 Play 모드에서 검증했습니다.\",\"next\":\"웨이브별 적 수·체력·등장 간격과 보스 난이도 조정, 더 많은 테스트를 통한 패치 전후 비교는 후속 과제입니다.\",\"limitation\":\"한정된 테스트 데이터입니다. 26회는 플레이 기록 수이며 서로 다른 이용자 26명을 뜻하지 않습니다. 소규모 설문을 일반 이용자 평가로 제시하지 않았습니다.\"},\"results\":{\"done\":[\"5개 스테이지, 3웨이브 전투와 보상 시스템의 프로토타입 빌드\",\"게임 기획 문서 v2.0을 기준으로 시스템·데이터 변경 내용 정리\",\"플레이로그 수집 및 동의 UI 구현, 기능 검증 보고서 작성\"],\"next\":[\"플레이 타임 및 난이도 목표 재검토\",\"원본 로그 기반 상세 지표 추가 분석과 패치 전후 재측정\",\"미완성 연출·리소스·전투 규칙 후속 검토\"]},\"sources\":[{\"title\":\"게임 개발 일지 · 21쪽\",\"url\":\"https://drive.google.com/file/d/1rtqe2c6sBIOkPuPYdNcWQaPfO4puyTGK/view\"},{\"title\":\"테스트 결과 보고서 · 11쪽\",\"url\":\"https://drive.google.com/file/d/1Da7oBTQOx46WYkXDCsARAvfEnRCkc26O/view\"},{\"title\":\"레벨 디자인 기획서\",\"url\":\"https://docs.google.com/document/d/1hE8OUefM8ScqxiZS7-MrG62J68TV3_8L9OP-g38IEdY/edit\"},{\"title\":\"전투 시스템 기획서\",\"url\":\"https://docs.google.com/document/d/1hDuiZyvJtkmh8qHvlQgvgdQsS4Q3TttVBel7-OiY23M/edit\"},{\"title\":\"개인프로젝트 WBS.xlsx\",\"url\":\"https://docs.google.com/spreadsheets/d/1v0ppYgPnlv_ISSwXf4SlckajI0BUEQag/edit\"},{\"title\":\"전투 / 레벨 디자인 기획서\",\"url\":\"https://docs.google.com/document/d/1yIKQ6oUNLq9Ybw01ebAFS7x7EEAH-ihw/edit\"},{\"title\":\"reward_data_table_completed.xlsx\",\"url\":\"https://docs.google.com/spreadsheets/d/1KpONoEKSe9oCQr8FfDvdlTzmFv0tqLaD/edit\"}],\"images\":{\"prototype\":\"data:image/webp;base64,\",\"characters\":\"data:image/webp;base64,\",\"arena\":\"data:image/webp;base64,\",\"boss\":\"data:image/webp;base64,\",\"reward\":\"data:image/webp;base64,\",\"status\":\"data:image/webp;base64,\",\"elements\":\"data:image/webp;base64,\"},\"documentImages\":{\"wbs_plan\":\"data:image/webp;base64,\",\"wbs_schedule\":\"data:image/webp;base64,\",\"level_concept\":\"data:image/webp;base64,";